/* eslint-disable max-lines */
/* eslint-disable max-lines-per-function */
/* eslint-disable @wordpress/no-unsafe-wp-apis */
/**
 * External dependencies
 */
import styled from '@emotion/styled';

/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import {
	ToggleControl,
	SelectControl,
	TextControl,
	Flex,
	FlexItem,
	Button,
	__experimentalNumberControl as NumberControl,
	__experimentalToolsPanel as ToolsPanel,
	__experimentalToolsPanelItem as ToolsPanelItem,
	__experimentalToggleGroupControl as ToggleGroupControl,
	__experimentalToggleGroupControlOption as ToggleGroupControlOption,
	PanelBody,
} from '@wordpress/components';
/**
 * Internal dependencies
 */
import { formatNum } from '../utils/helpers';

const PanelDescription = styled.div`
	grid-column: span 2;
`;
const WidePanelItem = styled(ToolsPanelItem)`
	grid-column: span 2;
`;
const SingleColumnItem = styled(ToolsPanelItem)`
	grid-column: span 1;
`;
const StyledLabel = styled.div`
	font-size: 11px;
	font-weight: 500;
	line-height: 1.4;
	text-transform: uppercase;
	display: inline-block;
	margin-bottom: calc(8px) !important;
	padding: 0px;
`;
const Help = styled.div`
	margin-top: calc(8px);
	font-size: 12px;
	font-style: normal;
	color: rgb(117, 117, 117);
	margin-bottom: 0px;
`;

function LabelControls({ attributes, setAttributes, clientId }) {
	const { layout, pie, labels, map, io } = attributes;
	const { type: chartType, orientation } = layout;
	const {
		active,
		labelCutoff,
		labelCutoffMobile,
		labelPositionBar,
		labelPositionDX,
		labelPositionDY,
		showFirstLastPointsOnly,
		absoluteValue,
		color,
		fontSize,
		truncateDecimal,
		toFixedDecimal,
		labelUnit,
		labelUnitPosition,
		toLocaleString,
	} = labels;
	const { chartData } = io;
	const { showCategoryLabels } = pie;
	const { ignoreSmallStateLabels } = map;
	// Check if any data points have custom label positions
	const hasCustomLabelPositions = chartData?.some(
		(d) => d.__labelPositions && Object.keys(d.__labelPositions).length > 0
	);

	// Reset all custom label positions
	const handleResetLabelPositions = () => {
		if (!chartData) return;

		const updatedData = chartData.map((d) => {
			if (d.__labelPositions) {
				const { __labelPositions, ...rest } = d;
				return rest;
			}
			return d;
		});

		setAttributes({
			io: {
				...io,
				chartData: updatedData,
			},
		});
	};
	return (
		<PanelBody title={__('Labels')} initialOpen={false}>
			<ToolsPanel
				label={__('Attributes')}
				panelId={clientId}
				style={{
					paddingLeft: '0',
					paddingRight: '0',
				}}
			>
				<ToolsPanelItem
					hasValue={() => true}
					label={__('Labels Active')}
					isShownByDefault
					panelId={clientId}
				>
					<ToggleControl
						label={__('Labels Active')}
						checked={active}
						onChange={() =>
							setAttributes({
								labels: {
									...labels,
									active: !active,
								},
							})
						}
					/>
					{'map-usa' === chartType && (
						<ToggleControl
							label={__('Ignore Small State Labels')}
							checked={ignoreSmallStateLabels}
							disabled={!active}
							onChange={() =>
								setAttributes({
									map: {
										...map,
										ignoreSmallStateLabels:
											!ignoreSmallStateLabels,
									},
								})
							}
						/>
					)}

					{'line' === chartType && (
						<ToolsPanelItem
							hasValue={() => true}
							label={__('Show First and Last Points Only')}
							isShownByDefault
							panelId={clientId}
						>
							<ToggleControl
								label={__('Display only first and last labels')}
								checked={showFirstLastPointsOnly}
								disabled={!active}
								onChange={() =>
									setAttributes({
										labels: {
											...labels,
											showFirstLastPointsOnly:
												!showFirstLastPointsOnly,
										},
									})
								}
							/>
						</ToolsPanelItem>
					)}
					{chartType === 'pie' && (
						<ToolsPanelItem
							hasValue={() => true}
							label={__('Category Labels Active')}
							isShownByDefault
							panelId={clientId}
						>
							<ToggleControl
								label={__('Category Labels Active')}
								checked={showCategoryLabels}
								onChange={() =>
									setAttributes({
										pie: {
											...pie,
											showCategoryLabels:
												!showCategoryLabels,
										},
									})
								}
							/>
						</ToolsPanelItem>
					)}
				</ToolsPanelItem>
				<WidePanelItem
					hasValue={() => fontSize}
					label={__('Label Font Size')}
					panelId={clientId}
				>
					<ToggleGroupControl
						__nextHasNoMarginBottom
						isBlock
						value={fontSize}
						label={__('Label Font Size')}
						disabled={!active}
						onChange={(value) => {
							setAttributes({
								labels: {
									...labels,
									fontSize: formatNum(value, 'integer'),
								},
							});
						}}
					>
						<ToggleGroupControlOption label="10px" value={10} />
						<ToggleGroupControlOption label="12px" value={12} />
						<ToggleGroupControlOption label="14px" value={14} />
						<ToggleGroupControlOption label="16px" value={16} />
					</ToggleGroupControl>
					<PanelDescription>
						<Help>
							{__(
								'Select the font size of the label. Default is 10px.'
							)}
						</Help>
					</PanelDescription>
				</WidePanelItem>
				<WidePanelItem
					hasValue={() => labelPositionDX}
					label={__('Label Positioning')}
					panelId={clientId}
					isShownByDefault
				>
					<PanelDescription>
						<StyledLabel>Label Positioning</StyledLabel>
					</PanelDescription>
					<Flex>
						<FlexItem>
							<NumberControl
								label={__('DX')}
								value={labelPositionDX}
								disabled={!active}
								onChange={(value) =>
									setAttributes({
										labels: {
											...labels,
											labelPositionDX: formatNum(
												value,
												'integer'
											),
										},
									})
								}
							/>
						</FlexItem>
						<FlexItem>
							<NumberControl
								label={__('DY')}
								value={labelPositionDY}
								disabled={!active}
								onChange={(value) =>
									setAttributes({
										labels: {
											...labels,
											labelPositionDY: formatNum(
												value,
												'integer'
											),
										},
									})
								}
							/>
						</FlexItem>
					</Flex>
					<PanelDescription>
						<Help>
							{__(
								"Select the position of the label relative to it's parent node, as well as any label units number formatting."
							)}
						</Help>
					</PanelDescription>
				</WidePanelItem>
				{hasCustomLabelPositions && (
					<WidePanelItem
						hasValue={() => hasCustomLabelPositions}
						label={__('Reset Custom Positions')}
						panelId={clientId}
					>
						<Button
							variant="secondary"
							isDestructive
							onClick={handleResetLabelPositions}
							disabled={!active}
						>
							{__('Reset All Label Positions')}
						</Button>
						<PanelDescription>
							<Help>
								{__(
									'Remove all custom label positions and return to default positioning.'
								)}
							</Help>
						</PanelDescription>
					</WidePanelItem>
				)}
				<WidePanelItem
					hasValue={() => absoluteValue}
					label={__('Absolute Value')}
					panelId={clientId}
				>
					<ToggleControl
						label={__('Absolute Value')}
						checked={absoluteValue}
						disabled={!active}
						onChange={() =>
							setAttributes({
								labels: {
									...labels,
									absoluteValue: !absoluteValue,
								},
							})
						}
					/>
					<PanelDescription>
						<Help>
							{__(
								'If the chart is displaying negative values, this will ensure the label is always positive. Often used on bar charts with a diverging axis.'
							)}
						</Help>
					</PanelDescription>
				</WidePanelItem>
				<WidePanelItem
					hasValue={() => toLocaleString}
					label={__('Format Value')}
					panelId={clientId}
					isShownByDefault
				>
					<ToggleControl
						label={__('Format Value to Locale String')}
						checked={toLocaleString}
						disabled={!active}
						onChange={() =>
							setAttributes({
								labels: {
									...labels,
									toLocaleString: !toLocaleString,
								},
							})
						}
					/>
					<PanelDescription>
						<Help>
							{__(
								'If checked, formats number into locale string (eg. 100000 -> 100,000).'
							)}
						</Help>
					</PanelDescription>
				</WidePanelItem>
				{/* HERE */}
				<WidePanelItem
					hasValue={() => truncateDecimal}
					label={__('Truncate Trailing Decimals')}
					panelId={clientId}
					isShownByDefault
				>
					<ToggleControl
						label={__('Truncate Trailing Decimals')}
						checked={truncateDecimal}
						disabled={!active}
						onChange={() =>
							setAttributes({
								labels: {
									...labels,
									truncateDecimal: !truncateDecimal,
								},
							})
						}
					/>
					<PanelDescription>
						<Help>
							{__(
								'If checked and number has fewer decimal places than the configuration requests, will remove all extraneous decimals from numbers. Eg. 1.6000 -> 1.6.'
							)}
						</Help>
					</PanelDescription>
				</WidePanelItem>
				<WidePanelItem
					hasValue={() => toFixedDecimal}
					label={__('Decimal Places')}
					panelId={clientId}
					isShownByDefault
				>
					<NumberControl
						label={__('Decimal Places')}
						value={toFixedDecimal}
						disabled={!active}
						min={0}
						max={100}
						onChange={(value) =>
							setAttributes({
								labels: {
									...labels,
									toFixedDecimal: formatNum(value, 'integer'),
								},
							})
						}
					/>
				</WidePanelItem>
				<WidePanelItem
					hasValue={() => labelUnit}
					label={__('Label Unit')}
					panelId={clientId}
					isShownByDefault
				>
					<TextControl
						label={__('Label Unit')}
						value={labelUnit}
						disabled={!active}
						onChange={(value) =>
							setAttributes({
								labels: {
									...labels,
									labelUnit: value,
								},
							})
						}
					/>
					<PanelDescription>
						<Help>{__('Add a unit to the label. eg. % or $')}</Help>
					</PanelDescription>
				</WidePanelItem>
				<WidePanelItem
					hasValue={() => labelUnitPosition}
					label={__('Label Unit Position')}
					panelId={clientId}
				>
					<ToggleGroupControl
						__nextHasNoMarginBottom
						isBlock
						value={labelUnitPosition}
						label="Label Unit Position"
						onChange={(type) => {
							setAttributes({
								labels: {
									...labels,
									labelUnitPosition: type,
								},
							});
						}}
					>
						<ToggleGroupControlOption label="Start" value="start" />
						<ToggleGroupControlOption label="End" value="end" />
					</ToggleGroupControl>
					<PanelDescription>
						<Help>
							{__(
								'Select the position of the label unit relative to the label.'
							)}
						</Help>
					</PanelDescription>
				</WidePanelItem>
				{('bar' === chartType ||
					'diverging-bar' === chartType ||
					'stacked-bar' === chartType ||
					'exploded-bar' === chartType) && (
					<>
						<WidePanelItem
							hasValue={() => labelPositionBar}
							label={__('Label Position')}
							panelId={clientId}
						>
							<ToggleGroupControl
								__nextHasNoMarginBottom
								isBlock
								value={labelPositionBar}
								disabled={!active}
								label="Bar Label Position"
								onChange={(type) => {
									setAttributes({
										labels: {
											...labels,
											labelPositionBar: type,
										},
									});
								}}
							>
								<ToggleGroupControlOption
									label="Inside"
									value="inside"
								/>
								<ToggleGroupControlOption
									label="Center"
									value="center"
								/>
								<ToggleGroupControlOption
									label="Outside"
									value="outside"
								/>
							</ToggleGroupControl>
							<PanelDescription>
								<Help>
									{__(
										'Select the position of the label relative to the bar.'
									)}
								</Help>
							</PanelDescription>
						</WidePanelItem>
						<SingleColumnItem
							hasValue={() => labelCutoff}
							label={__('Label Cutoff')}
							panelId={clientId}
						>
							<NumberControl
								label={__('🖥️ Label Cutoff')}
								value={labelCutoff}
								disabled={
									!active || 'outside' === labelPositionBar
								}
								onChange={(value) =>
									setAttributes({
										labels: {
											...labels,
											labelCutoff: formatNum(
												value,
												'integer'
											),
										},
									})
								}
							/>
							<PanelDescription>
								<Help>
									{__(
										'Hide labels that are smaller than this value.'
									)}
								</Help>
							</PanelDescription>
						</SingleColumnItem>
						<SingleColumnItem
							hasValue={() => labelCutoffMobile}
							label={__('Label Cutoff Mobile')}
							panelId={clientId}
						>
							<NumberControl
								label={__('📱 Label Cutoff')}
								value={labelCutoffMobile}
								disabled={
									!active ||
									'outside' === labelPositionBar ||
									'vertical' === orientation
								}
								onChange={(value) =>
									setAttributes({
										labels: {
											...labels,
											labelCutoffMobile: formatNum(
												value,
												'integer'
											),
										},
									})
								}
							/>
							<PanelDescription>
								<Help>
									{__(
										'Hide labels that are smaller than this value on mobile.'
									)}
								</Help>
							</PanelDescription>
						</SingleColumnItem>
					</>
				)}
				<WidePanelItem
					hasValue={() => color}
					label={__('Label Color')}
					panelId={clientId}
				>
					<SelectControl
						label={__('Label Color')}
						value={color}
						disabled={!active}
						onChange={(value) =>
							setAttributes({
								labels: {
									...labels,
									color: value,
								},
							})
						}
						options={[
							{ label: __('Contrast'), value: 'contrast' },
							{ label: __('Inherit'), value: 'inherit' },
							{ label: __('Black'), value: 'black' },
							{ label: __('White'), value: 'white' },
						]}
					/>
					<PanelDescription>
						<Help>
							{__(
								'Select the color of the label. Contrast will determine color based on bar background for optimal contrast.'
							)}
						</Help>
					</PanelDescription>
				</WidePanelItem>
			</ToolsPanel>
		</PanelBody>
	);
}

export default LabelControls;
