/**
 * WordPress Dependencies
 */
// import { ResizableBox, Spinner } from '@wordpress/components';
import { useSelect } from '@wordpress/data';
import {
	useBlockProps,
	useInnerBlocksProps,
	store as blockEditorStore,
} from '@wordpress/block-editor';
import { store as editorStore } from '@wordpress/editor';

/**
 * External Dependencies
 */
import {
	ChartBuilderWrapper,
	ChartBuilderTextWrapper,
} from '@prc/charting-library';
// eslint-disable-next-line
import { memo, useEffect, useMemo, useState } from 'react';

/**
 * Internal Dependencies
 */
import { formatCellContent } from '../utils/helpers';
import ChartControls from './chart-controls';
import getConfig from '../utils/get-config';
// import CopyPasteStylesHandler from './copy-paste-styles-handler';
import { TitleSubtitle, Footer } from './meta-text-fields';
import { createWpEditorFunctions } from './wp-editor-functions';
import { AlignmentOverlay } from './alignment-overlay';
import { DrawingOverlay } from './drawing-overlay';
import { DrawingLayer } from './drawing-layer';

const getCellContent = (cell) => {
	return (
		cell.content?.originalContent ||
		cell.content?.originalHTML ||
		cell.content?.text ||
		cell.content
	);
};

/**
 * Memoized wrapper for ChartBuilderWrapper to prevent re-renders during drag.
 * This ensures that alignment state updates don't break drag interactions.
 */
const MemoizedChartBuilder = memo(
	({ className, config, data, wpEditorFunctions }) => (
		<ChartBuilderWrapper
			className={className}
			config={config}
			data={data}
			wpEditorFunctions={wpEditorFunctions}
		/>
	)
);

export default function Edit({
	attributes: attrs,
	setAttributes,
	toggleSelection,
	clientId,
	isSelected,
	context,
}) {
	const { io, metadata, dataRender, drawings = [], layout } = attrs;

	const { chartData, isStaticChart, isFreeformChart } = io;
	const { height, width } = layout;
	const { groupBreaksCategory, mapScale } = dataRender || {};

	// Use the controller id to create a unique id for the chart.
	const controllerId = context['prc-chart-builder/id'];

	// Use the context-provided controller ID instead of getBlockParentsByBlockName
	// to correctly scope to the nearest parent controller.
	// This fixes data leakage when charts are nested inside Freeform charts.
	const { tableData, parentBlockId, refId } = useSelect(
		(select) => {
			const { getBlocks } = select(blockEditorStore);
			const { getCurrentPostId, getCurrentPostType } =
				select(editorStore);

			// The controller provides its ID via context, and sets id = clientId on init.
			// Using context ensures we get the nearest parent controller, not an outer one.
			const parentControllerId = controllerId;

			// Find the table block among the parent controller's children
			let tableAttributes = null;
			if (parentControllerId) {
				const controllerChildren = getBlocks(parentControllerId);
				const tableBlock = controllerChildren?.find(
					(block) =>
						'core/table' === block.name ||
						'prc-block/table' === block.name
				);
				if (tableBlock) {
					tableAttributes = tableBlock.attributes;
				}
			}

			const editorContextPostType = getCurrentPostType();

			let postId = null;
			if (context && context.refId) {
				postId = context.refId;
			} else if ('chart' === editorContextPostType) {
				postId = getCurrentPostId();
			}

			return {
				tableData: tableAttributes,
				parentBlockId: parentControllerId,
				refId: postId,
				editorPostType: editorContextPostType,
			};
		},
		[context, controllerId]
	);
	const editorClickEvent = () => {
		console.log('editorClickEvent...');
	};

	// Alignment state for visual guides during drag
	const [alignments, setAlignments] = useState({
		vertical: [],
		horizontal: [],
	});

	// Track drag state to disable tooltips during drag
	const [isDragging, setIsDragging] = useState(false);

	// Editor functions for chart interactions
	// IMPORTANT: setAlignments and setIsDragging are NOT in dependencies to avoid recreating on every state change
	const wpEditorFunctions = useMemo(
		() =>
			createWpEditorFunctions({
				attrs,
				setAttributes,
				toggleSelection,
				setAlignments, // Pass alignment setter (stable reference)
				setIsDragging, // Pass drag state setter (stable reference)
			}),
		[attrs, setAttributes, toggleSelection] // setAlignments and setIsDragging intentionally excluded
	);

	const config = useMemo(() => {
		const baseConfig = getConfig(attrs, clientId, editorClickEvent);

		// Add IDs to annotations
		if (baseConfig.annotations?.items) {
			baseConfig.annotations.items = baseConfig.annotations.items.map(
				(annotation, index) => ({
					...annotation,
					id: String(index),
				})
			);
		}

		// Disable tooltips during drag to prevent conflicts
		if (isDragging) {
			baseConfig.tooltip = {
				...baseConfig.tooltip,
				active: false,
				activeOnMobile: false,
			};
		}

		return baseConfig;
	}, [attrs, clientId, isDragging]);

	const headers = useMemo(
		() =>
			tableData
				? tableData.head[0].cells.map((c) => getCellContent(c))
				: [],
		[tableData]
	);

	const body = useMemo(() => (tableData ? tableData.body : []), [tableData]);

	const memoizedChartData = useMemo(
		() =>
			body.map((row) =>
				row.cells.reduce((acc, cell, index) => {
					const key = 0 === index ? 'x' : headers[index];
					return {
						...acc,
						[key]: formatCellContent(
							getCellContent(cell),
							key,
							mapScale,
							groupBreaksCategory,
							dataRender?.xScale,
							dataRender?.xFormat
						),
					};
				}, {})
			),
		[
			body,
			headers,
			mapScale,
			groupBreaksCategory,
			dataRender?.xScale,
			dataRender?.xFormat,
		]
	);

	useEffect(() => {
		if (!headers || headers.length === 0) {
			return;
		}
		if (!memoizedChartData || memoizedChartData.length === 0) {
			return;
		}

		const [, ...rest] = headers;

		// Check if we have custom positions to preserve in the current chartData
		const hasCustomPositions = chartData?.some(
			(d) =>
				d.__labelPositions && Object.keys(d.__labelPositions).length > 0
		);

		let newChartData = memoizedChartData;
		if (hasCustomPositions) {
			// Create lookup map of old positions by x-value
			const positionsMap = new Map();
			chartData.forEach((d) => {
				if (d.__labelPositions) {
					positionsMap.set(d.x, d.__labelPositions);
				}
			});

			// Merge positions into new data where x-values match
			newChartData = memoizedChartData.map((d) => {
				const existingPositions = positionsMap.get(d.x);
				if (existingPositions) {
					return { ...d, __labelPositions: existingPositions };
				}
				return d;
			});
		}

		// Update all io properties at once to avoid race conditions
		// Include the id derived from controllerId to ensure it's always set
		const chartId = controllerId ? `${controllerId}-chart` : attrs.io?.id;
		setAttributes({
			io: {
				...(attrs.io || {}),
				id: chartId,
				availableCategories: rest,
				independentVariable: headers[0],
				chartData: newChartData,
			},
		});
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [headers, memoizedChartData, setAttributes, controllerId]);

	const blockProps = useBlockProps({
		className: 'active',
	});

	const innerBlocksProps = useInnerBlocksProps();

	// Drawing state
	const [isDrawingMode, setIsDrawingMode] = useState(false);
	const [drawingTool, setDrawingTool] = useState('pen');
	const [strokeColor, setStrokeColor] = useState('#000000');
	const [strokeWidth, setStrokeWidth] = useState(2);

	function handleDrawingComplete(drawingData) {
		setAttributes({
			drawings: [...(drawings || []), drawingData],
		});
	}

	function handleDrawingModeChange(mode) {
		setIsDrawingMode(mode);
	}

	function handleToolChange(tool) {
		setDrawingTool(tool);
	}

	return (
		<>
			<ChartControls
				attributes={attrs}
				setAttributes={setAttributes}
				parentBlock={parentBlockId}
				clientId={clientId}
				isDrawingMode={isDrawingMode}
				drawingTool={drawingTool}
				onDrawingModeChange={handleDrawingModeChange}
				onToolChange={handleToolChange}
				strokeColor={strokeColor}
				strokeWidth={strokeWidth}
				onStrokeColorChange={setStrokeColor}
				onStrokeWidthChange={setStrokeWidth}
			/>
			{/* <CopyPasteStylesHandler
				id={id}
				attributes={attrs}
				setAttributes={setAttributes}
			> */}
			<div {...blockProps}>
				<figure>
					<ChartBuilderTextWrapper
						active={config.metadata.active}
						width={width}
						horizontalRules={config.layout.horizontalRules}
					>
						{metadata.active && (
							<TitleSubtitle
								attributes={attrs}
								setAttributes={setAttributes}
							/>
						)}
						{/* <ResizableBox
								size={{
									height,
									width,
								}}
								minHeight="50"
								minWidth="50"
								enable={{
									top: false,
									right: false,
									bottom: false,
									left: false,
									topRight: false,
									bottomRight: !!isSelected,
									bottomLeft: false,
									topLeft: false,
								}}
								onResizeStop={(
									event,
									direction,
									elt,
									delta
								) => {
									setAttributes({
										height: parseInt(
											parseInt(height, 10) +
												parseInt(delta.height, 10),
											10
										),
										width: parseInt(
											parseInt(width, 10) +
												parseInt(delta.width, 10),
											10
										),
									});
									toggleSelection(true);
								}}
								onResizeStart={() => {
									toggleSelection(false);
								}}
							> */}
						{(isStaticChart || isFreeformChart) && (
							<div className="cb__chart" {...innerBlocksProps} />
						)}
						{!isStaticChart &&
							!isFreeformChart &&
							memoizedChartData && (
								<div style={{ position: 'relative' }}>
									<MemoizedChartBuilder
										className="cb__chart"
										config={config}
										data={chartData || memoizedChartData}
										wpEditorFunctions={wpEditorFunctions}
									/>
									<DrawingLayer
										drawings={drawings}
										chartDimensions={{
											width,
											height,
											padding: config.layout.padding,
										}}
										chartWidth={width}
										chartHeight={height}
									/>
									<AlignmentOverlay
										alignments={alignments}
										chartDimensions={{
											width,
											height,
											padding: config.layout.padding,
										}}
									/>
									{isSelected && (
										<DrawingOverlay
											isActive={isDrawingMode}
											tool={drawingTool}
											onDrawingComplete={
												handleDrawingComplete
											}
											chartDimensions={{
												width,
												height,
												padding: config.layout.padding,
											}}
											chartWidth={width}
											chartHeight={height}
											strokeColor={strokeColor}
											strokeWidth={strokeWidth}
										/>
									)}
								</div>
							)}
						{/* </ResizableBox> */}
						{metadata.active && (
							<Footer
								attributes={attrs}
								setAttributes={setAttributes}
							/>
						)}
					</ChartBuilderTextWrapper>
				</figure>
			</div>
			{/* </CopyPasteStylesHandler> */}
		</>
	);
}
