// V2
/* eslint-disable max-lines-per-function */
/**
 * External dependencies
 */
import styled from '@emotion/styled';
/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import {
	PanelBody,
	__experimentalNumberControl as NumberControl,
	__experimentalToolsPanel as ToolsPanel,
	__experimentalToolsPanelItem as ToolsPanelItem,
	ToggleControl,
	RangeControl,
} from '@wordpress/components';
/**
 * Internal dependencies
 */
import { formatNum } from '../utils/helpers';

const PanelDescription = styled.div`
	grid-column: span 2;
`;
const WidePanelItem = styled(ToolsPanelItem)`
	grid-column: span 2;
`;
const StyledLabel = styled.div`
	font-size: 11px;
	font-weight: 500;
	line-height: 1.4;
	text-transform: uppercase;
	display: inline-block;
	margin-bottom: calc(8px) !important;
	padding: 0px;
`;
function DivergingBarControls({ attributes, setAttributes, clientId }) {
	const { divergingBar, bar } = attributes;
	const { barPadding } = bar;
	const { percentOfInnerWidth, neutralBar } = divergingBar;
	const { active, offsetX, separator, separatorOffsetX } = neutralBar;
	return (
		<PanelBody title={__('Diverging Bar')} initialOpen>
			<ToolsPanel
				label={__('Attributes')}
				panelId={clientId}
				style={{
					paddingLeft: '0',
					paddingRight: '0',
				}}
			>
				<WidePanelItem
					hasValue={() => true}
					label={__('Bar Padding')}
					isShownByDefault
					panelId={clientId}
				>
					<NumberControl
						label={__('Bar Padding')}
						withInputField
						min={0}
						max={10}
						step={0.05}
						value={parseFloat(barPadding, 10)}
						onChange={(value) => {
							setAttributes({
								bar: {
									...bar,
									barPadding: formatNum(value, 'float'),
								},
							});
						}}
					/>
				</WidePanelItem>
				<WidePanelItem
					hasValue={() => true}
					label={__('Neutral Bar')}
					isShownByDefault
					panelId={clientId}
				>
					<ToggleControl
						label={__('Neutral Bar Active')}
						checked={active}
						onChange={() =>
							setAttributes({
								divergingBar: {
									...divergingBar,
									neutralBar: {
										...neutralBar,
										active: !active,
									},
								},
							})
						}
						help={__(
							'If active, a neutral bar will be added to the chart. This bar will be positioned to the right of the main graphic.'
						)}
					/>
					<ToggleControl
						label={__('Neutral Bar Separator')}
						checked={separator}
						onChange={() =>
							setAttributes({
								divergingBar: {
									...divergingBar,
									neutralBar: {
										...neutralBar,
										separator: !separator,
									},
								},
							})
						}
						help={__(
							'If active, a separator will be added to the neutral bar.'
						)}
					/>
				</WidePanelItem>
				<WidePanelItem
					hasValue={() => offsetX}
					label={__('Neutral Bar Positioning')}
					panelId={clientId}
				>
					<PanelDescription>
						<StyledLabel>Neutral Bar Positioning</StyledLabel>
					</PanelDescription>
					<NumberControl
						label={__('DX')}
						value={offsetX}
						disabled={!active}
						onChange={(value) =>
							setAttributes({
								divergingBar: {
									...divergingBar,
									neutralBar: {
										...neutralBar,
										offsetX: formatNum(value, 'integer'),
									},
								},
							})
						}
					/>
				</WidePanelItem>
				<WidePanelItem
					hasValue={() => separatorOffsetX}
					label={__('Neutral Bar Positioning')}
					panelId={clientId}
				>
					<PanelDescription>
						<StyledLabel>Separator Positioning</StyledLabel>
					</PanelDescription>
					<NumberControl
						label={__('DX')}
						value={separatorOffsetX}
						disabled={!separator}
						onChange={(value) =>
							setAttributes({
								divergingBar: {
									...divergingBar,
									neutralBar: {
										...neutralBar,
										separatorOffsetX: formatNum(
											value,
											'integer'
										),
									},
								},
							})
						}
					/>
				</WidePanelItem>
				<WidePanelItem
					hasValue={() => percentOfInnerWidth}
					label={__('Diverging Bar Width')}
					panelId={clientId}
				>
					<RangeControl
						label={__('Percent of Inner Width')}
						withInputField
						disabled={!active}
						min={0}
						max={100}
						value={percentOfInnerWidth}
						onChange={(w) =>
							setAttributes({
								divergingBar: {
									...divergingBar,
									percentOfInnerWidth: formatNum(
										w,
										'integer'
									),
								},
							})
						}
					/>
				</WidePanelItem>
			</ToolsPanel>
		</PanelBody>
	);
}

export default DivergingBarControls;
