import blockMetadata from '../block.json';

// Extract flat attributes for v1 deprecation
const nested_keys = [
	'layout',
	'metadata',
	'colors',
	'plotBands',
	'independentAxis',
	'dependentAxis',
	'tooltip',
	'legend',
	'labels',
	'bar',
	'line',
	'dotPlot',
	'explodedBar',
	'pie',
	'nodes',
	'map',
	'divergingBar',
	'diffColumn',
	'annotations',
	'dataRender',
	'animate',
	'io',
	'_legacy',
	'_version',
];

const v1Attributes = {};
for (const [key, value] of Object.entries(blockMetadata.attributes)) {
	if (!nested_keys.includes(key)) {
		v1Attributes[key] = value;
	}
}

export default v1Attributes;
