// V2
/* eslint-disable max-lines */
/* eslint-disable @wordpress/no-unsafe-wp-apis */
/* eslint-disable max-lines-per-function */
/* eslint-disable indent */
/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import {
	PanelBody,
	PanelRow,
	TextControl,
	ToggleControl,
	Flex,
	FlexItem,
	__experimentalNumberControl as NumberControl,
	SelectControl,
	AnglePickerControl,
	__experimentalToggleGroupControl as ToggleGroupControl,
	__experimentalToggleGroupControlOption as ToggleGroupControlOption,
} from '@wordpress/components';
/**
 * Internal dependencies
 */
import { PanelColorSettings } from '@wordpress/block-editor';
import { formatNum } from '../utils/helpers';

function DependentAxisControls({ attributes, setAttributes }) {
	const { dependentAxis } = attributes;

	const {
		active,
		label,
		domain,
		showZero,
		tickMarksActive,
		tickCount,
		tickValues,
		ticksToLocaleString,
		abbreviateTicks,
		abbreviateTicksDecimals,
		tickUnit,
		tickUnitPosition,
		tickLabels,
		axisLabel,
		axis,
		grid,
	} = dependentAxis;
	return (
		<PanelBody
			title={__('Dependent Axis Configuration')}
			initialOpen={false}
		>
			<PanelRow>
				Dependent variables are properties that change in response to a
				change in another property. As such, the dependent axis is
				usually the y-axis.
			</PanelRow>
			<ToggleControl
				label="Axis active"
				help={active ? 'Shows axis.' : 'No y-axis.'}
				checked={active}
				onChange={() =>
					setAttributes({
						dependentAxis: { ...dependentAxis, active: !active },
					})
				}
			/>
			<TextControl
				label={__('Label')}
				value={label}
				onChange={(val) =>
					setAttributes({
						dependentAxis: { ...dependentAxis, label: val },
					})
				}
			/>
			<NumberControl
				label={__('Label Padding')}
				help={__('Determines the space between the label and the axis')}
				value={axisLabel.padding}
				disableUnits
				disabledUnits
				onChange={(val) =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							axisLabel: {
								...axisLabel,
								padding: formatNum(val, 'integer'),
							},
						},
					})
				}
			/>
			<NumberControl
				label={__('Label Width')}
				help={__(
					'Determines the width of the label. Shorten to break label to multiple lines.'
				)}
				value={axisLabel.maxWidth}
				disableUnits
				disabledUnits
				onChange={(val) =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							axisLabel: {
								...axisLabel,
								maxWidth: formatNum(val, 'integer'),
							},
						},
					})
				}
			/>
			<PanelRow>Y Domain</PanelRow>
			<Flex>
				<FlexItem>
					<NumberControl
						label={__('Minimum')}
						value={domain[0]}
						disableUnits
						disabledUnits
						onChange={(val) =>
							setAttributes({
								dependentAxis: {
									...dependentAxis,
									domain: [
										formatNum(val, 'integer'),
										domain[1],
									],
								},
							})
						}
					/>
				</FlexItem>
				<FlexItem>
					<NumberControl
						label={__('Maximum')}
						value={domain[1]}
						disableUnits
						disabledUnits
						onChange={(val) =>
							setAttributes({
								dependentAxis: {
									...dependentAxis,
									domain: [
										domain[0],
										formatNum(val, 'integer'),
									],
								},
							})
						}
					/>
				</FlexItem>
			</Flex>
			<PanelRow>Axis Ticks and Tick Labels</PanelRow>
			<ToggleControl
				label={__('Show tick marks')}
				help={tickMarksActive ? 'Shows tick marks.' : 'No tick marks.'}
				checked={tickMarksActive}
				onChange={() =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							tickMarksActive: !tickMarksActive,
						},
					})
				}
			/>
			<NumberControl
				label={__('Number of ticks')}
				value={tickCount}
				disableUnits
				disabledUnits
				min={1}
				onChange={(val) =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							tickCount: formatNum(val, 'integer'),
						},
					})
				}
				help={__(
					'Note: This is return approximately the number of ticks requested, deferring to number that will evenly space ticks on the bar.'
				)}
			/>
			<ToggleControl
				label="Show min domain label"
				help={__(
					"Forces the minimum domain value's lable to appear on axis. May overlap with independent axis."
				)}
				checked={showZero}
				onChange={() =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							showZero: !showZero,
						},
					})
				}
			/>
			<TextControl
				label={__('Specific Ticks')}
				value={tickValues}
				onChange={(val) =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							tickValues: val,
						},
					})
				}
				help={__(
					'List of numbers seperated by commas (eg. 0, 50, 100). Setting this value will override the "Number of ticks" parameter'
				)}
			/>
			<ToggleControl
				label={__('Abbreviate ticks')}
				help={
					abbreviateTicks
						? __(
								'Tick values will be abbreviated when possible (eg. 100,000 -> 100K)'
							)
						: __('Tick values will be displayed as-is')
				}
				checked={abbreviateTicks}
				onChange={() =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							abbreviateTicks: !abbreviateTicks,
						},
					})
				}
			/>
			<NumberControl
				label={__(
					'Abbreviated tick to set decimal place (when applicable)'
				)}
				value={abbreviateTicksDecimals}
				disabled={!abbreviateTicks}
				disableUnits
				disabledUnits
				min={0}
				onChange={(val) =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							abbreviateTicksDecimals: formatNum(val, 'integer'),
						},
					})
				}
			/>
			<ToggleControl
				label={__('Format ticks to locale string')}
				disabled={ticksToLocaleString}
				help={
					ticksToLocaleString
						? __(
								'Tick values will be formatted to locale string (eg. 100000 -> 100,000)'
							)
						: __('Tick values will be displayed as-is')
				}
				checked={ticksToLocaleString}
				onChange={() =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							ticksToLocaleString: !ticksToLocaleString,
						},
					})
				}
			/>
			<TextControl
				label={__('Tick Units')}
				value={tickUnit}
				onChange={(val) =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							tickUnit: val,
						},
					})
				}
			/>
			<SelectControl
				label={__('Tick Unit Position')}
				value={tickUnitPosition}
				options={[
					{
						value: 'start',
						label: 'Start',
					},
					{
						value: 'end',
						label: 'End',
					},
				]}
				onChange={(type) => {
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							tickUnitPosition: type,
						},
					});
				}}
			/>
			<PanelRow className="components-base-control__label">
				Label Size and Positioning
			</PanelRow>
			<ToggleGroupControl
				__nextHasNoMarginBottom
				isBlock
				value={tickLabels.fontSize}
				label={__('Tick Label Font Size')}
				onChange={(value) => {
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							tickLabels: {
								...tickLabels,
								fontSize: formatNum(value, 'integer'),
							},
						},
					});
				}}
			>
				<ToggleGroupControlOption label="10px" value={10} />
				<ToggleGroupControlOption label="12px" value={12} />
				<ToggleGroupControlOption label="14px" value={14} />
				<ToggleGroupControlOption label="16px" value={16} />
			</ToggleGroupControl>
			<Flex>
				<FlexItem>
					<NumberControl
						label={__('DX')}
						value={tickLabels.dx}
						onChange={(value) =>
							setAttributes({
								dependentAxis: {
									...dependentAxis,
									tickLabels: {
										...tickLabels,
										dx: formatNum(value, 'integer'),
									},
								},
							})
						}
					/>
				</FlexItem>
				<FlexItem>
					<NumberControl
						label={__('DY')}
						value={tickLabels.dy}
						onChange={(value) =>
							setAttributes({
								dependentAxis: {
									...dependentAxis,
									tickLabels: {
										...tickLabels,
										dy: formatNum(value, 'integer'),
									},
								},
							})
						}
					/>
				</FlexItem>
			</Flex>

			<AnglePickerControl
				label={__('Tick Label Angle')}
				__nextHasNoMarginBottom
				value={tickLabels.angle}
				onChange={(val) =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							tickLabels: {
								...tickLabels,
								angle: formatNum(val, 'integer'),
							},
						},
					})
				}
			/>
			<NumberControl
				label={__('Tick Label Max Width')}
				value={tickLabels.maxWidth}
				disableUnits
				disabledUnits
				onChange={(val) =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							tickLabels: {
								...tickLabels,
								maxWidth: formatNum(val, 'integer'),
							},
						},
					})
				}
				help={__(
					'Determines the width of the tick label. Shorten to break label to multiple lines.'
				)}
			/>
			<ToggleGroupControl
				__nextHasNoMarginBottom
				isBlock
				label="Tick Label Vertical Anchor"
				value={tickLabels.verticalAnchor}
				onChange={(type) => {
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							tickLabels: {
								...tickLabels,
								verticalAnchor: type,
							},
						},
					});
				}}
			>
				<ToggleGroupControlOption label="Start" value="start" />
				<ToggleGroupControlOption label="Middle" value="middle" />
				<ToggleGroupControlOption label="End" value="end" />
			</ToggleGroupControl>
			<ToggleGroupControl
				__nextHasNoMarginBottom
				isBlock
				label="Tick Label Text Anchor"
				value={tickLabels.textAnchor}
				onChange={(type) => {
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							tickLabels: {
								...tickLabels,
								textAnchor: type,
							},
						},
					});
				}}
			>
				<ToggleGroupControlOption label="Start" value="start" />
				<ToggleGroupControlOption label="Middle" value="middle" />
				<ToggleGroupControlOption label="End" value="end" />
			</ToggleGroupControl>
			<PanelColorSettings
				__experimentalHasMultipleOrigins
				__experimentalIsRenderedInSidebar
				title={__('Axis Styles')}
				initialOpen
				colorSettings={[
					{
						value: axis.stroke,
						onChange: (value) =>
							setAttributes({
								dependentAxis: {
									...dependentAxis,
									axis: { ...axis, stroke: value },
								},
							}),
						label: __('Axis Stroke'),
					},
					{
						value: grid.stroke,
						onChange: (value) =>
							setAttributes({
								dependentAxis: {
									...dependentAxis,
									grid: { ...grid, stroke: value },
								},
							}),
						label: __('Grid Stroke'),
					},
					{
						value: tickLabels.fill,
						onChange: (value) =>
							setAttributes({
								dependentAxis: {
									...dependentAxis,
									tickLabels: { ...tickLabels, fill: value },
								},
							}),
						label: __('Text Fill'),
					},
				]}
			/>
			<NumberControl
				label={__('Grid Opacity')}
				value={grid.strokeOpacity}
				step={0.1}
				min={0}
				max={1}
				disableUnits
				disabledUnits
				onChange={(val) =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							grid: {
								...grid,
								strokeOpacity: formatNum(val, 'integer'),
							},
						},
					})
				}
			/>
			<TextControl
				label={__('Grid Stroke Dasharray')}
				value={grid.strokeDasharray}
				onChange={(val) =>
					setAttributes({
						dependentAxis: {
							...dependentAxis,
							grid: { ...grid, strokeDasharray: val },
						},
					})
				}
			/>
		</PanelBody>
	);
}

export default DependentAxisControls;
