/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import {
	TextareaControl,
	TextControl,
	ToggleControl,
	PanelBody,
} from '@wordpress/components';

import { generateDefaultAltText } from '../utils/helpers';

function TextFieldControls({ attributes, setAttributes }) {
	const { metadata, io, layout } = attributes;

	const { active, title, subtitle, note, source, tag, alt } = metadata;
	const {
		questionWording,
		questionWordingActive,
		isStaticChart,
		staticImageAltText,
	} = io;
	const { type: chartType, horizontalRules } = layout;
	return (
		<PanelBody title={__('Text Fields')} initialOpen={false}>
			<ToggleControl
				label={__('Text Fields Active')}
				help={__(
					'Enables title, subtitle, note, source, and tag fields for chart.'
				)}
				checked={active}
				onChange={() =>
					setAttributes({
						metadata: {
							...metadata,
							active: !active,
						},
					})
				}
			/>
			<ToggleControl
				label={__('Show horizontal rules')}
				help={__('Show horizontal rules above and below chart')}
				checked={horizontalRules}
				onChange={() =>
					setAttributes({
						layout: {
							...layout,
							horizontalRules: !horizontalRules,
						},
					})
				}
			/>
			<TextControl
				label={__('Title')}
				value={title}
				onChange={(val) =>
					setAttributes({
						metadata: {
							...metadata,
							title: val,
							alt:
								val.length > 0
									? val
									: generateDefaultAltText(chartType, val),
						},
					})
				}
			/>
			<TextControl
				label={__('Subtitle')}
				value={subtitle}
				onChange={(val) =>
					setAttributes({
						metadata: {
							...metadata,
							subtitle: val,
						},
					})
				}
			/>
			{isStaticChart && (
				<TextareaControl
					label={__('Static Image Alt Text')}
					help="Enter the alt text for the static image"
					value={staticImageAltText}
					onChange={(val) =>
						setAttributes({
							io: {
								...io,
								staticImageAltText: val,
							},
						})
					}
				/>
			)}
			{!isStaticChart && (
				<TextareaControl
					label={__('Alt Text (Accessibility)')}
					help={
						alt
							? __('Custom alt text set')
							: `Default: ${generateDefaultAltText(chartType, title)}`
					}
					value={alt}
					placeholder={generateDefaultAltText(chartType, title)}
					onChange={(val) =>
						setAttributes({
							metadata: {
								...metadata,
								alt: val,
							},
						})
					}
				/>
			)}
			<ToggleControl
				label={__('Question Wording Active')}
				help={__('If active, enables question wording field for chart')}
				checked={questionWordingActive}
				onChange={() =>
					setAttributes({
						io: {
							...io,
							questionWordingActive: !questionWordingActive,
						},
					})
				}
			/>
			<TextareaControl
				label={__('Question Wording')}
				help={__('Optional: Add the question wording for the chart')}
				value={questionWording}
				onChange={(val) =>
					setAttributes({
						io: {
							...io,
							questionWording: val,
						},
					})
				}
			/>
			<TextareaControl
				label={__('Note')}
				help="Enter the note for the chart"
				value={note}
				onChange={(val) =>
					setAttributes({
						metadata: {
							...metadata,
							note: val,
						},
					})
				}
			/>
			<TextareaControl
				label={__('Source')}
				help="Enter the source of the chart"
				value={source}
				onChange={(val) =>
					setAttributes({
						metadata: {
							...metadata,
							source: val,
						},
					})
				}
			/>
			<TextControl
				label={__('Tag')}
				value={tag}
				onChange={(val) =>
					setAttributes({
						metadata: {
							...metadata,
							tag: val,
						},
					})
				}
			/>
		</PanelBody>
	);
}

export default TextFieldControls;
