// V2
/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import {
	PanelBody,
	SelectControl,
	__experimentalNumberControl as NumberControl,
} from '@wordpress/components';
/**
 * Internal dependencies
 */
import { formatNum } from '../utils/helpers';

const NodeControls = ({ attributes, setAttributes }) => {
	const { nodes } = attributes;
	const { pointSize, pointFill, pointStrokeWidth } = nodes;
	return (
		<PanelBody title={__('Node Styles')} initialOpen={false}>
			<NumberControl
				min={1}
				label={__('Node Size')}
				value={pointSize}
				onChange={(value) =>
					setAttributes({
						nodes: {
							...nodes,
							pointSize: formatNum(value, 'integer'),
						},
					})
				}
			/>
			<NumberControl
				min={1}
				label={__('Node Stroke Width')}
				value={pointStrokeWidth}
				onChange={(value) =>
					setAttributes({
						nodes: {
							...nodes,
							pointStrokeWidth: formatNum(value, 'integer'),
						},
					})
				}
			/>
			<SelectControl
				label={__('Node Fill')}
				options={[
					{ label: 'Inherit', value: 'inherit' },
					{ label: 'White', value: 'white' },
				]}
				value={pointFill}
				onChange={(value) =>
					setAttributes({
						nodes: {
							...nodes,
							pointFill: value,
						},
					})
				}
			/>
		</PanelBody>
	);
};

export default NodeControls;
