/* eslint-disable @wordpress/i18n-no-variables */
/* eslint-disable @wordpress/i18n-no-flanking-whitespace */
/* eslint-disable @wordpress/no-unsafe-wp-apis */
/* eslint-disable max-lines */
/* eslint-disable max-lines-per-function */
/**
 * WordPress dependencies
 */
import { __ } from '@wordpress/i18n';
import {
	PanelBody,
	PanelRow,
	TextControl,
	ToggleControl,
	SelectControl,
	Flex,
	FlexItem,
	__experimentalNumberControl as NumberControl,
	AnglePickerControl,
	__experimentalToggleGroupControl as ToggleGroupControl,
	__experimentalToggleGroupControlOption as ToggleGroupControlOption,
} from '@wordpress/components';
/**
 * Internal dependencies
 */
import { PanelColorSettings } from '@wordpress/block-editor';
import { formatNum } from '../utils/helpers';

function IndependentAxisControls({ attributes, setAttributes }) {
	const { layout, independentAxis, dataRender } = attributes;
	const { type: chartType } = layout;
	const {
		active,
		label,
		scale,
		dateFormat,
		domain,
		showZero,
		tickMarksActive,
		tickCount,
		tickValues,
		ticksToLocaleString,
		abbreviateTicks,
		abbreviateTicksDecimals,
		tickUnit,
		tickUnitPosition,
		tickLabels,
		axisLabel,
		axis,
		grid,
	} = independentAxis;
	const { xFormat } = dataRender;

	return (
		<PanelBody
			title={__('Independent Axis Configuration')}
			initialOpen={false}
		>
			<PanelRow>
				The independent axis is almost always the x-axis, except in
				cases of horizontal bar charts or stack bar charts, where the
				independent values are plotted on the y-axis.
			</PanelRow>
			<ToggleControl
				label="Axis active"
				help={active ? 'Shows axis.' : 'No axis.'}
				checked={active}
				onChange={() =>
					setAttributes({
						independentAxis: {
							...independentAxis,
							active: !active,
						},
					})
				}
			/>
			<TextControl
				label={__('Label')}
				value={label}
				onChange={(val) =>
					setAttributes({
						independentAxis: { ...independentAxis, label: val },
					})
				}
			/>
			<NumberControl
				label={__('Label Padding')}
				help={__('Determines the space between the label and the axis')}
				value={axisLabel.padding}
				disableUnits
				disabledUnits
				onChange={(val) =>
					setAttributes({
						independentAxis: {
							...independentAxis,
							axisLabel: {
								...axisLabel,
								padding: formatNum(val, 'integer'),
							},
						},
					})
				}
			/>
			<NumberControl
				label={__('Label Width')}
				help={__(
					'Determines the width of the label. Shorten to break label to multiple lines.'
				)}
				value={axisLabel.maxWidth}
				disableUnits
				disabledUnits
				onChange={(val) =>
					setAttributes({
						independentAxis: {
							...independentAxis,
							axisLabel: {
								...axisLabel,
								maxWidth: formatNum(val, 'integer'),
							},
						},
					})
				}
			/>
			<SelectControl
				label={__('Independent axis scale')}
				value={scale}
				options={[
					{
						value: 'linear',
						label: 'Linear',
					},
					{
						value: 'time',
						label: 'Time',
					},
				]}
				onChange={(val) => {
					setAttributes({
						independentAxis: { ...independentAxis, scale: val },
					});
				}}
			/>
			{'time' === scale && (
				<SelectControl
					label={__('Time scale format')}
					value={dateFormat}
					options={[
						{ value: '%Y', label: '2023' },
						{ value: '’%y', label: '’23' },
						{ value: '%-m/%Y', label: '4/2023' },
						{ value: '%-m/%y', label: '4/23' },
						{ value: '%m/%Y', label: '04/2023' },
						{ value: '%m/%y', label: '04/23' },
						{ value: '%B %Y', label: 'April 2023' },
						{ value: '%b %Y', label: 'Apr 2023' },
						{ value: '%B ’%y', label: 'April ’23' },
						{ value: '%b ’%y', label: 'Apr ’23' },
						{ value: '%-m/%-d/%Y', label: '4/15/2023' },
						{ value: '%-d/%-m/%Y', label: '15/4/2023' },
						{ value: '%-m/%-d/%y', label: '4/15/23' },
						{ value: '%-d/%-m/%y', label: '15/4/23' },
						{ value: '%-m/%-d', label: '4/15' },
						{ value: '%-d/%-m', label: '15/4' },
						{ value: '%m/%d/%Y', label: '04/15/2023' },
						{ value: '%d/%m/%Y', label: '15/04/2023' },
						{ value: '%m/%d/%y', label: '04/15/23' },
						{ value: '%d/%m/%y', label: '15/04/23' },
						{ value: '%m/%-d', label: '04/15' },
						{ value: '%-d/%m', label: '15/04' },
						{ value: '%B %-d, %Y', label: 'April 15, 2023' },
						{ value: '%B %-d %Y', label: 'April 15 2023' },
						{ value: '%b %-d, %Y', label: 'Apr 15, 2023' },
						{ value: '%b %-d %Y', label: 'Apr 15 2023' },
						{ value: '%-d %B, %Y', label: '15 April, 2023' },
						{ value: '%-d %B %Y', label: '15 April 2023' },
						{ value: '%-d %b, %Y', label: '15 Apr, 2023' },
						{ value: '%-d %b %Y', label: '15 Apr 2023' },
						{ value: '%B %-d ’%y', label: 'April 15 ’23' },
						{ value: '%-d %B ’%y', label: '15 April ’23' },
						{ value: '%b %-d ’%y', label: 'Apr 15 ’23' },
						{ value: '%-d %b ’%y', label: '15 Apr ’23' },
						{ value: '%B %-d', label: 'April 15' },
						{ value: '%-d %B', label: '15 April' },
						{ value: '%b %-d', label: 'Apr 15' },
						{ value: '%-d %b', label: '15 Apr' },
						{ value: '%B', label: 'April' },
						{ value: '%b', label: 'Apr' },
					]}
					onChange={(val) => {
						setAttributes({
							independentAxis: {
								...independentAxis,
								dateFormat: val,
							},
						});
					}}
				/>
			)}
			<PanelRow>Domain</PanelRow>
			<Flex>
				<FlexItem>
					<NumberControl
						label={__('Minimum')}
						value={domain[0]}
						disabled={
							'stacked-bar' === chartType ||
							'bar' === chartType ||
							'pie' === chartType
						}
						disableUnits
						disabledUnits
						onChange={(val) => {
							setAttributes({
								independentAxis: {
									...independentAxis,
									domain: [
										formatNum(val, 'integer'),
										domain[1],
									],
								},
							});
						}}
					/>
				</FlexItem>
				<FlexItem>
					<NumberControl
						label={__('Maximum')}
						value={domain[1]}
						disabled={
							'stacked-bar' === chartType ||
							'bar' === chartType ||
							'pie' === chartType
						}
						disableUnits
						disabledUnits
						onChange={(val) => {
							setAttributes({
								independentAxis: {
									...independentAxis,
									domain: [
										domain[0],
										formatNum(val, 'integer'),
									],
								},
							});
						}}
					/>
				</FlexItem>
			</Flex>

			<PanelRow>Axis Ticks and Tick Labels</PanelRow>
			<ToggleControl
				label={__('Show tick marks')}
				help={tickMarksActive ? 'Shows tick marks.' : 'No tick marks.'}
				checked={tickMarksActive}
				onChange={() =>
					setAttributes({
						independentAxis: {
							...independentAxis,
							tickMarksActive: !tickMarksActive,
						},
					})
				}
			/>
			<NumberControl
				label={__('Number of ticks')}
				value={tickCount}
				disableUnits
				disabledUnits
				onChange={(val) =>
					setAttributes({
						independentAxis: {
							...independentAxis,
							tickCount: formatNum(val, 'integer'),
						},
					})
				}
				help={__(
					'Note: This is return approximately the number of ticks requested, deferring to number that will evenly space ticks on the bar.'
				)}
			/>
			<ToggleControl
				label="Show min domain label"
				help={__(
					"Forces the minimum domain value's lable to appear on axis. May overlap with dependent axis."
				)}
				checked={showZero}
				onChange={() =>
					setAttributes({
						independentAxis: {
							...independentAxis,
							showZero: !showZero,
						},
					})
				}
			/>
			<TextControl
				label={__('Specific Ticks')}
				value={tickValues}
				onChange={(val) =>
					setAttributes({
						independentAxis: {
							...independentAxis,
							tickValues: val,
						},
					})
				}
				help={__(
					`List of numbers seperated by commas (eg. 0, 50, 100). Setting this value will override the "Number of Ticks" parameter. ${'time' === scale ? `If independent axis is time scale, ticks must match the date input format (${xFormat}).` : ''}`
				)}
			/>
			{'time' !== scale && (
				<>
					<ToggleControl
						label={__('Abbreviate ticks')}
						help={
							abbreviateTicks
								? __(
										'Tick values will be abbreviated when possible (eg. 100,000 -> 100K)'
									)
								: __('Tick values will be displayed as-is')
						}
						checked={abbreviateTicks}
						onChange={() =>
							setAttributes({
								independentAxis: {
									...independentAxis,
									abbreviateTicks: !abbreviateTicks,
								},
							})
						}
					/>
					<NumberControl
						label={__(
							'Abbreviated tick to set decimal place (when applicable)'
						)}
						value={abbreviateTicksDecimals}
						disabled={!abbreviateTicks}
						disableUnits
						disabledUnits
						min={0}
						onChange={(val) =>
							setAttributes({
								independentAxis: {
									...independentAxis,
									abbreviateTicksDecimals: formatNum(
										val,
										'integer'
									),
								},
							})
						}
					/>
					<ToggleControl
						label={__('Format ticks to locale string')}
						disabled={abbreviateTicks}
						help={
							ticksToLocaleString
								? __(
										'Tick values will be formatted to locale string (eg. 100000 -> 100,000)'
									)
								: __('Tick values will be displayed as-is')
						}
						checked={ticksToLocaleString}
						onChange={() =>
							setAttributes({
								independentAxis: {
									...independentAxis,
									ticksToLocaleString: !ticksToLocaleString,
								},
							})
						}
					/>
				</>
			)}
			<TextControl
				label={__('Tick Units')}
				value={tickUnit}
				onChange={(val) =>
					setAttributes({
						independentAxis: { ...independentAxis, tickUnit: val },
					})
				}
			/>
			<SelectControl
				label={__('Tick Unit Position')}
				value={tickUnitPosition}
				options={[
					{
						value: 'start',
						label: 'Start',
					},
					{
						value: 'end',
						label: 'End',
					},
				]}
				onChange={(type) => {
					setAttributes({
						independentAxis: {
							...independentAxis,
							tickUnitPosition: type,
						},
					});
				}}
			/>
			<PanelRow className="components-base-control__label">
				Label Size and Positioning
			</PanelRow>
			<ToggleGroupControl
				__nextHasNoMarginBottom
				isBlock
				value={tickLabels.fontSize}
				label={__('Tick Label Font Size')}
				onChange={(value) => {
					setAttributes({
						independentAxis: {
							...independentAxis,
							tickLabels: {
								...tickLabels,
								fontSize: formatNum(value, 'integer'),
							},
						},
					});
				}}
			>
				<ToggleGroupControlOption label="10px" value={10} />
				<ToggleGroupControlOption label="12px" value={12} />
				<ToggleGroupControlOption label="14px" value={14} />
				<ToggleGroupControlOption label="16px" value={16} />
			</ToggleGroupControl>
			<PanelRow>
				Determines the position of tick label relative to it’s parent
				node
			</PanelRow>
			<Flex>
				<FlexItem>
					<NumberControl
						label={__('DX')}
						value={tickLabels.dx}
						onChange={(value) =>
							setAttributes({
								independentAxis: {
									...independentAxis,
									tickLabels: {
										...tickLabels,
										dx: formatNum(value, 'integer'),
									},
								},
							})
						}
					/>
				</FlexItem>
				<FlexItem>
					<NumberControl
						label={__('DY')}
						value={tickLabels.dy}
						onChange={(value) =>
							setAttributes({
								independentAxis: {
									...independentAxis,
									tickLabels: {
										...tickLabels,
										dy: formatNum(value, 'integer'),
									},
								},
							})
						}
					/>
				</FlexItem>
			</Flex>
			<AnglePickerControl
				label={__('Tick Label Angle')}
				__nextHasNoMarginBottom
				value={tickLabels.angle}
				onChange={(val) =>
					setAttributes({
						independentAxis: {
							...independentAxis,
							tickLabels: {
								...tickLabels,
								angle: formatNum(val, 'integer'),
							},
						},
					})
				}
			/>
			<NumberControl
				label={__('Tick Label Max Width')}
				value={tickLabels.maxWidth}
				disableUnits
				disabledUnits
				onChange={(val) =>
					setAttributes({
						independentAxis: {
							...independentAxis,
							tickLabels: {
								...tickLabels,
								maxWidth: formatNum(val, 'integer'),
							},
						},
					})
				}
				help={__(
					'Determines the width of the tick label. Shorten to break label to multiple lines.'
				)}
			/>

			<ToggleGroupControl
				__nextHasNoMarginBottom
				isBlock
				value={tickLabels.verticalAnchor}
				label="Tick Label Vertical Anchor"
				onChange={(type) => {
					setAttributes({
						independentAxis: {
							...independentAxis,
							tickLabels: {
								...tickLabels,
								verticalAnchor: type,
							},
						},
					});
				}}
			>
				<ToggleGroupControlOption label="Start" value="start" />
				<ToggleGroupControlOption label="Middle" value="middle" />
				<ToggleGroupControlOption label="End" value="end" />
			</ToggleGroupControl>
			<ToggleGroupControl
				__nextHasNoMarginBottom
				isBlock
				value={tickLabels.textAnchor}
				label="Tick Label Text Anchor"
				onChange={(type) => {
					setAttributes({
						independentAxis: {
							...independentAxis,
							tickLabels: {
								...tickLabels,
								textAnchor: type,
							},
						},
					});
				}}
			>
				<ToggleGroupControlOption label="Start" value="start" />
				<ToggleGroupControlOption label="Middle" value="middle" />
				<ToggleGroupControlOption label="End" value="end" />
			</ToggleGroupControl>
			<PanelColorSettings
				__experimentalHasMultipleOrigins
				__experimentalIsRenderedInSidebar
				title={__('Axis Styles')}
				initialOpen
				colorSettings={[
					{
						value: axis.stroke,
						onChange: (value) =>
							setAttributes({
								independentAxis: {
									...independentAxis,
									axis: { ...axis, stroke: value },
								},
							}),
						label: __('Axis Stroke'),
					},
					{
						value: grid.stroke,
						onChange: (value) =>
							setAttributes({
								independentAxis: {
									...independentAxis,
									grid: { ...grid, stroke: value },
								},
							}),
						label: __('Grid Stroke'),
					},
					{
						value: tickLabels.fill,
						onChange: (value) =>
							setAttributes({
								independentAxis: {
									...independentAxis,
									tickLabels: { ...tickLabels, fill: value },
								},
							}),
						label: __('Text Fill'),
					},
				]}
			/>
			<NumberControl
				label={__('Grid Opacity')}
				value={grid.strokeOpacity}
				disableUnits
				disabledUnits
				step={0.1}
				min={0}
				max={1}
				onChange={(val) =>
					setAttributes({
						independentAxis: {
							...independentAxis,
							grid: {
								...grid,
								strokeOpacity: formatNum(val, 'integer'),
							},
						},
					})
				}
			/>
			<TextControl
				label={__('Grid Stroke Dasharray')}
				value={grid.strokeDasharray}
				onChange={(val) =>
					setAttributes({
						independentAxis: {
							...independentAxis,
							grid: { ...grid, strokeDasharray: val },
						},
					})
				}
			/>
		</PanelBody>
	);
}

export default IndependentAxisControls;
