import { RichText } from '@wordpress/block-editor';
import { useState } from '@wordpress/element';

import { Icon } from '@prc/icons';

const TitleSubtitle = ({ attributes, setAttributes }) => {
	const { metadata } = attributes;
	const { title, subtitle } = metadata;
	return (
		<>
			<RichText
				className="cb__title"
				value={title}
				onChange={(content) =>
					setAttributes({
						metadata: {
							...metadata,
							title: content,
						},
					})
				}
				placeholder={title}
			/>
			<RichText
				className="cb__subtitle"
				value={subtitle}
				onChange={(content) =>
					setAttributes({
						metadata: {
							...metadata,
							subtitle: content,
						},
					})
				}
				placeholder={subtitle}
			/>
		</>
	);
};

const Footer = ({ attributes, setAttributes }) => {
	const { io, metadata } = attributes;
	const { questionWording, questionWordingActive } = io;
	const { note, source, tag } = metadata;
	const [isOpen, setIsOpen] = useState(false);
	const toggleQuestionWordingExpanded = () => {
		setIsOpen(!isOpen);
	};
	return (
		<>
			{questionWordingActive && (
				<>
					<div
						className="cb__note cb__note--question-wording-button"
						onClick={() => toggleQuestionWordingExpanded()}
						role="button"
						tabIndex={0}
						onKeyDown={(e) => {
							if (e.key === 'Enter' || e.key === ' ') {
								toggleQuestionWordingExpanded();
							}
						}}
					>
						<Icon
							icon={isOpen ? 'circle-minus' : 'circle-plus'}
							library="light"
						/>
						<span hidden={isOpen}>
							Expand to find question wording
						</span>

						<span hidden={!isOpen}>Collapse question wording</span>
					</div>
					{isOpen && (
						<>
							<RichText
								className="cb__note cb__note--question-wording"
								value={questionWording}
								onChange={(content) =>
									setAttributes({
										io: {
											...io,
											questionWording: content,
										},
									})
								}
								placeholder={questionWording}
							/>
						</>
					)}
				</>
			)}
			<RichText
				className="cb__note"
				value={note}
				onChange={(content) =>
					setAttributes({
						metadata: {
							...metadata,
							note: content,
						},
					})
				}
				placeholder={note}
			/>
			<RichText
				className="cb__note"
				value={source}
				onChange={(content) =>
					setAttributes({
						metadata: {
							...metadata,
							source: content,
						},
					})
				}
				placeholder={source}
			/>
			<RichText
				className="cb__tag"
				value={tag}
				onChange={(content) =>
					setAttributes({
						metadata: {
							...metadata,
							tag: content,
						},
					})
				}
				placeholder={tag}
			/>
		</>
	);
};

export { TitleSubtitle, Footer };
